  const xDir = side === "left" ? -1 : 1;

  return (
    <div
      style={{
        opacity: progress,
        transform: `translateX(${interpolate(progress, [0, 1], [xDir * 80, 0])}px)`,
        display: "flex",
        alignItems: "center",
        gap: 40,
        backgroundColor: "#1E1B3A",
        border: `3px solid rgba(255,255,255,0.18)`,
        borderRadius: 36,
        padding: "52px 72px",
        position: "relative",
        minWidth: 660,
      }}
    >
      <span style={{ fontSize: 100 }}>{icon}</span>
      <span style={{ fontSize: 64, fontWeight: 700, color: COLORS.white }}>
        {label}
      </span>
      <div
        style={{
          position: "absolute",
          top: -26,
          right: -26,
          width: 100,
          height: 100,
          borderRadius: "50%",
          backgroundColor: "#3D1515",
          border: "3px solid #FF4444",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: xProgress,
          transform: `scale(${interpolate(xProgress, [0, 1], [0, 1])})`,
        }}
      >
        <svg width="48" height="48" viewBox="0 0 24 24" fill="none">
          <line
            x1="6" y1="6" x2="18" y2="18"
