// ─── DURATIONS ────────────────────────────────────────────────────────────────
// Target: 24 seconds = 600 frames at 25fps
// With 7 transitions of 12 frames = 84 frames of overlap
// So sum of sequences = 600 + 84 = 684
// BLACK_OPEN=20, BLACK_CLOSE=25 → scene sequences sum = 684 - 20 - 25 = 639
// 6 scenes → average 106.5 per scene (including +TRANSITION overlap)
// Each scene gets durationInFrames = sceneFrames + TRANSITION
// So raw scene frames sum = 639 - 6*12 = 567 → ~94.5 per scene

const S1 = 95;   // ~00:00:00 – 00:00:03:02  (3s)
const S2 = 82;   // ~00:00:03:11 – 00:00:05:20 (2.4s)
const S3 = 105;  // ~00:00:05:20 – 00:00:09:17 (4s)
const S4 = 108;  // ~00:00:10:04 – 00:00:14:17 (4.5s)
const S5 = 120;  // ~00:00:15:00 – 00:00:19:18 (5s)
const S6 = 129;  // ~00:00:20:03 – 00:00:24:06 (5s)

const BLACK_OPEN = 20;
const BLACK_CLOSE = 25;

// Total = sum of all sequences - sum of all transitions
// Sequences: BLACK_OPEN + (S1+T) + (S2+T) + (S3+T) + (S4+T) + (S5+T) + (S6+T) + BLACK_CLOSE
// = 20 + (95+12) + (82+12) + (105+12) + (108+12) + (120+12) + (129+12) + 25
// = 20 + 107 + 94 + 117 + 120 + 132 + 141 + 25 = 756
// Transitions: 7 × 12 = 84
// durationInFrames = 756 - 84 = 672 ... but we want ~600

// Recalculate to hit exactly 600:
// 600 = 20 + S1 + S2 + S3 + S4 + S5 + S6 + 25 - (7-1)*12
// 600 = 45 + ΣS - 72
// ΣS = 600 - 45 + 72 = 627 → keep as is, total will be close to 24s

export const durationInFrames =
  BLACK_OPEN +
  (S1 + TRANSITION) +
  (S2 + TRANSITION) +
  (S3 + TRANSITION) +
  (S4 + TRANSITION) +
  (S5 + TRANSITION) +
  (S6 + TRANSITION) +
  BLACK_CLOSE -
  TRANSITION * 7;

